examples.code:
整数型の配列: data ← {3, 9, 2, 7, 5}
整数型: max ← data[1]
整数型: i
for (i を 2 から dataの要素数 まで 1 ずつ増やす)
  if (data[i] > max)
    max ← data[i]
  endif
endfor
出力 max

整数型の配列: a ← {5, 3, 8, 1, 4}
整数型: i, j, t
for (i を aの要素数 から 2 まで 1 ずつ減らす)
  for (j を 1 から i - 1 まで 1 ずつ増やす)
    if (a[j] > a[j + 1])
      t ← a[j]
      a[j] ← a[j + 1]
      a[j + 1] ← t
    endif
  endfor
endfor
出力 a

○整数型: fact(整数型: n)
  if (n ≦ 1)
    return 1
  endif
  return n × fact(n - 1)

出力 fact(5)

○整数型: fib(整数型: n)
  if (n < 2)
    return n
  endif
  return fib(n - 1) + fib(n - 2)

出力 fib(6)

integer array: data ← {3, 9, 2, 7, 5}
integer: max ← data[1]
integer: i
for (i from 2 to length(data) step 1)
  if (data[i] > max)
    max ← data[i]
  endif
endfor
output max

integer array: a ← {5, 3, 8, 1, 4}
integer: i, j, t
for (i from length(a) down to 2 step 1)
  for (j from 1 to i - 1 step 1)
    if (a[j] > a[j + 1])
      t ← a[j]
      a[j] ← a[j + 1]
      a[j + 1] ← t
    endif
  endfor
endfor
output a

